package com.rioni.lk.api.controller;

import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.CrossOrigin;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import com.rioni.lk.api.dto.ProfileDto;

@RestController
@RequestMapping("/api/")
@CrossOrigin(origins = "*", allowedHeaders = "*")
public class ProfileController {

    @GetMapping("/simpleProfile")
    public ResponseEntity<ProfileDto> getSampleProfile() {
        ProfileDto profile = new ProfileDto();
        profile.setId(12345L);
        profile.setNbs("NBS123456");
        profile.setNdu("NDU789012");
        profile.setName("Иван");
        profile.setSurname("Иванов");
        profile.setPatronymic("Иванович");
        profile.setPhotoUrl(
                "data:image/png;base64,");
        profile.setEmail("ivan.ivanov@example.com");
        profile.setPhone("+79123456789");
        profile.setDateOfBirth("1995-05-11");
        profile.setGender("Мужской");
        profile.setCitizenship("Российская федерация");
        profile.setPlaceOfBirth("Россия, Москва, ул. Ленина, д. 1, кв. 1");
        profile.setDocumentType("Паспорт");
        profile.setPassportNumber("76 85948434");
        profile.setPassportIssueDate("2010-02-20");
        profile.setPassportExpiryDate("2030-02-20");

        return ResponseEntity.ok(profile);
    }
}